/* ---------- widget ---------- */
function onTheory(root){const w=root.querySelector('#w-touch');if(!w)return;
  w.innerHTML=`<label>q₁ = <output id="wq1">8</output> нКл<input type="range" id="wQ1" min="-10" max="10" step="1" value="8"></label>
<label>q₂ = <output id="wq2">-2</output> нКл<input type="range" id="wQ2" min="-10" max="10" step="1" value="-2"></label>
<div class="row" style="margin:6px 0"><button class="btn ghost" id="wT">Коснуться шариками</button></div>
<div id="wS" style="display:flex;justify-content:center"></div><div id="wO" class="small" style="text-align:center;margin-top:6px"></div>`;
  const A=w.querySelector('#wQ1'),B=w.querySelector('#wQ2');
  const mode=(a,b)=>a===0&&b===0?'none':a*b>0?'rep':'att';
  const draw=(msg)=>{const a=+A.value,b=+B.value;w.querySelector('#wq1').textContent=SG(a);w.querySelector('#wq2').textContent=SG(b);
    w.querySelector('#wS').innerHTML=balls(a?(a>0?'+':'−'):'0',b?(b>0?'+':'−'):'0',mode(a,b),{l1:SG(a),l2:SG(b)});
    const m=mode(a,b);w.querySelector('#wO').innerHTML=(msg||'')+(m==='rep'?'Одноимённые — <span class="out">отталкиваются</span>.':m==='att'?(a*b<0?'Разноимённые — <span class="out">притягиваются</span>.':'Заряженный шарик <span class="out">притягивает</span> незаряженный (через влияние).'):'Оба не заряжены — не взаимодействуют.')+` Сумма зарядов: <span class="out">${SG(a+b)} нКл</span>.`;};
  A.oninput=B.oninput=()=>draw();
  w.querySelector('#wT').onclick=()=>{const a=+A.value,b=+B.value,s=(a+b)/2;if(!Number.isInteger(s)){draw(`Полусумма ${N(s)} — не целая; выбери заряды с чётной суммой. `);return;}A.value=s;B.value=s;draw(`После касания: (${SG(a)} + ${P(b)})/2 = ${SG(s)} нКл у каждого. `);};
  draw();}

